"""Portable flightline diagnosis page; no network resources or executable paths."""
import html
import json
from pathlib import Path


def write(folder, result):
    escape=lambda value:html.escape(str(value),quote=True)
    def number(value):return '—' if value is None else f'{value:.4f}'
    sections=[]
    for index,state in enumerate(result['states']):
        name='baseline' if index==0 else 'candidate'
        flights=''.join('<tr>'+''.join('<td>'+escape(v)+'</td>' for v in (
            r['id'],r['source_id'],r['trajectory_path'] or 'No trajectory — declared LAS line identity',
            f"{r['ground_returns']:,}",r['occupied_cells'],r['ground_cells'],r['qualified_cells'],
            ', '.join(map(str,r['supported_neighbors'])) or 'No supported neighbor',
            '; '.join(f'{k}: {n}' for k,n in r['rejected_cells'].items()) or '—'))+'</tr>' for r in state['flights'])
        pairs=''.join(f'<tr data-state="{index}" data-pair="{r["a"]}-{r["b"]}">'+''.join('<td>'+escape(v)+'</td>' for v in (
            f"{r['a']} / {r['b']}",r['occupied_shared_cells'],r['ground_shared_cells'],r['statistics']['cells'],
            number(r['statistics']['median']),number(r['statistics']['rmse']),number(r['statistics']['p95_abs']),
            r['finding'],
            (f"E {number(r['trend']['east_gradient_per_1000ft'])}; N {number(r['trend']['north_gradient_per_1000ft'])}"
             if r['trend']['available'] else r['trend']['reason'])))+'</tr>' for r in state['pairs'])
        connected='; '.join(', '.join(map(str,component)) for component in state['connected_components'])
        inputs=''.join('<li>'+escape(c['path'])+'</li>' for c in state['inventory']['clouds'])
        marks=''.join('<tr>'+''.join('<td>'+escape(v)+'</td>' for v in (
            mark['id'],mark['role'],number(mark['easting']),number(mark['northing']),
            ', '.join(map(str,mark['qualified_cell_flights'])) or 'No qualified cell',mark['assessment']))+'</tr>' for mark in state.get('reference_locations',[]))
        sections.append(f'''<section><h2>{name.title()} flightlines</h2><p>Supported-overlap components: <strong>{escape(connected)}</strong>. Connections require at least {result['config']['min_cells']} qualified shared cells. A component does not establish calibration or absolute accuracy.</p>
        <div class="scroll"><table><thead><tr><th>Analysis flight</th><th>LAS line</th><th>Trajectory / identity basis</th><th>Ground returns</th><th>Occupied cells</th><th>Ground cells</th><th>Qualified cells</th><th>Supported neighbors</th><th>Rejected-cell reasons</th></tr></thead><tbody>{flights}</tbody></table></div>
        <h3>Flight-pair differences</h3><p>Positive dZ means flight B is above flight A. All differences use {escape(state['units'])}. Trend values are {escape(state['units'])} per 1000 US survey ft, estimated only when spatial geometry supports them. Click a row to select its map.</p>
        <div class="scroll"><table><thead><tr><th>A / B</th><th>Shared occupied cells</th><th>Shared ground cells</th><th>Qualified cells</th><th>Median dZ</th><th>RMS dZ</th><th>P95 |dZ|</th><th>Finding</th><th>Spatial trend</th></tr></thead><tbody>{pairs or '<tr><td colspan="9">At least two flight identities are needed for pair comparisons.</td></tr>'}</tbody></table></div>
        <h3>Survey reference locations</h3><p>Locations use the baseline report CSVs and declared roles. Qualified ground cells provide a coverage screen only; target support and survey residuals are not measured. Candidate interpretation assumes the same declared vertical reference.</p><div class="scroll"><table><thead><tr><th>ID</th><th>Declared role</th><th>Easting</th><th>Northing</th><th>Flights with a qualified cell here</th><th>Scope</th></tr></thead><tbody>{marks or '<tr><td colspan="6">No reference locations supplied; control coverage and absolute accuracy remain unassessed.</td></tr>'}</tbody></table></div><p class="downloads"><a href="{name}/flightlines.csv">Flightlines CSV</a><a href="{name}/pairs.csv">Pairs CSV</a><a href="{name}/coverage_cells.csv">Observed coverage cells</a><a href="{name}/surface_cells.csv">All ground surface cells and rejection reasons</a><a href="{name}/overlap_cells.csv">All qualified pair cells</a><a href="{name}.project.json">Exact project snapshot</a></p><details><summary>Source clouds</summary><ul>{inputs}</ul></details></section>''')
    comparison=''
    if result['comparison'] is not None:
        rows=''.join('<tr>'+''.join('<td>'+escape(v)+'</td>' for v in (
            f"{r['a']} / {r['b']}",r['before']['cells'],number(r['before']['median']),number(r['after']['median']),
            number(r['before']['rmse']),number(r['after']['rmse']),
            'Enough common cells for review' if r['supported'] else 'Insufficient common support'))+'</tr>' for r in result['comparison']['pairs'])
        comparison=f'''<section><h2>Baseline / candidate on common support</h2><p>{escape(result['comparison']['note'])}</p><p>{escape(result['comparison']['matching'])}. Baseline-only and candidate-only flights remain in their own inventories; common comparisons exclude them.</p><div class="scroll"><table><thead><tr><th>A / B (baseline IDs)</th><th>Common cells</th><th>Before median</th><th>After median</th><th>Before RMS</th><th>After RMS</th><th>Support</th></tr></thead><tbody>{rows}</tbody></table></div><p><a href="common_cells.csv">Every common-cell before/after residual</a></p></section>'''
    raw=json.dumps(result,allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    baseline=result['states'][0]
    findings=''.join('<li>'+escape(x)+'</li>' for x in result['limitations'])
    template='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>pyArgus — Flightline diagnostics</title><style>
    *{box-sizing:border-box}body{margin:0;background:#0f1216;color:#dbe3ec;font:15px/1.6 'Segoe UI',sans-serif}main{max-width:1500px;margin:auto;padding:30px}h1{font-size:34px;margin:5px 0}h2{font-size:23px}h3{font-size:18px;margin-top:24px}.eyebrow,.muted{color:#8a97a6}section{background:#161b22;border:1px solid #2a323d;padding:20px;margin-top:22px;border-radius:6px}.notice{border-left:4px solid #ffb648;padding:15px 20px;background:#1c232c}.cards,.plots{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-top:20px}.card{background:#161b22;border:1px solid #2a323d;padding:15px}.card strong{display:block;font-size:25px;color:#4da3ff}.plots{grid-template-columns:1fr 1fr}canvas{width:100%;height:380px;background:#0f1216;border:1px solid #2a323d}.controls{display:flex;flex-wrap:wrap;gap:16px;align-items:center}.controls select{max-width:100%}select,button{padding:8px;background:#1c232c;color:#dbe3ec;border:1px solid #2a323d;font:inherit}a{color:#69b8ff}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:10px;text-align:left;border-bottom:1px solid #2a323d}th{background:#1c232c}td{vertical-align:top}tr[data-pair]{cursor:pointer}tr[data-pair]:hover{background:#1c232c}.scroll{overflow:auto}.downloads{display:flex;gap:16px;flex-wrap:wrap}li{overflow-wrap:anywhere}.legend{font-size:13px;color:#8a97a6}#map-note{min-height:25px}details{margin-top:18px}summary{cursor:pointer}@media(max-width:800px){.cards{grid-template-columns:1fr 1fr}.plots{grid-template-columns:1fr}main{padding:15px}canvas{height:320px}}@media print{body{background:white;color:black}section,.card{background:white;color:black}.scroll{overflow:visible}.controls{display:none}a{color:#145d8b}}
    </style></head><body><main><div class="eyebrow">pyArgus · read-only diagnosis · __CREATED__</div><h1>Flightline diagnostics</h1><p class="notice"><strong>No corrections applied.</strong> This report describes observed ground-surface agreement. It does not approve a dataset, identify the physical cause of a mismatch, or assess independent absolute accuracy.</p>
    <div class="cards"><div class="card"><strong>__FLIGHTS__</strong>baseline analysis flights</div><div class="card"><strong>__PAIRS__</strong>baseline pairs with sufficient qualified cells</div><div class="card"><strong>__COMPONENTS__</strong>supported-overlap components</div><div class="card"><strong>Not assessed</strong>independent absolute accuracy</div></div>
    <section><h2>Coverage and height disagreement</h2><div class="controls"><label>Dataset <select id="dataset"></select></label><label>Flight pair <select id="pair"></select></label></div><div class="plots"><div><h3>Observed flight coverage</h3><canvas id="coverage" aria-label="Observed flightline coverage map"></canvas><p class="legend">Blue: one flight · amber: two · purple: three or more. Each displayed cell has its actual observed flight count; the map may be sampled. Noise classes 7 and 18 are excluded. N is up.</p></div><div><h3>Qualified ground difference: B − A</h3><canvas id="difference" aria-label="Qualified flight pair residual map"></canvas><p class="legend">Blue: B lower · pale: near zero · red: B higher. Color saturates at ±__TOL__ __UNIT__. Blank areas are unassessed.</p></div></div><p id="map-note" class="muted"></p><p id="hover" class="legend">Move over a sampled difference cell for its coordinates and residual.</p></section>
    __COMMON____SECTIONS__<section><h2>Method and limitations</h2><p>__METHOD__</p><p>Cell width: __CELL__ US survey ft. Minimum ground returns: __MIN__. Maximum local plane RMS: __SCATTER__ US survey ft. Maximum slope: __SLOPE__. Plane-design condition must be ≤30; all four quadrants must contain ground returns around the cell center. These are screening settings, not accuracy standards.</p><ul>__LIMITATIONS__</ul><p><a href="diagnostics.json">Complete machine-readable evidence and settings</a></p></section></main><script id="data" type="application/json">__DATA__</script><script>
    const D=JSON.parse(document.getElementById('data').textContent),S=document.getElementById('dataset'),P=document.getElementById('pair');let selected=null,lastTransform=null;
    const colors=['#69b8ff','#ffb648','#4ad07a','#dd9ef9','#ff7185','#d7dd75','#56d9cf','#b5b8ff'];
    D.states.forEach((s,i)=>S.add(new Option(i?'Candidate':'Baseline',i)));
    function setup(c,bounds){const box=c.getBoundingClientRect();c.width=Math.max(300,Math.round(box.width));c.height=Math.round(box.height);const ctx=c.getContext('2d');ctx.fillStyle='#0f1216';ctx.fillRect(0,0,c.width,c.height);let [x0,x1,y0,y1]=bounds;const scale=Math.min((c.width-70)/Math.max(1,x1-x0),(c.height-55)/Math.max(1,y1-y0));const ox=(c.width-(x1-x0)*scale)/2,oy=(c.height-(y1-y0)*scale)/2;ctx.fillStyle='#8a97a6';ctx.font='11px Segoe UI';ctx.fillText('N ↑',15,20);return {ctx,map:(x,y)=>[ox+(x-x0)*scale,c.height-oy-(y-y0)*scale],scale};}
    function draw(){const s=D.states[+S.value],r=s.pairs.find(p=>`${p.a}-${p.b}`===P.value);selected=r;const all=s.flights.flatMap(f=>f.map_cells),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]);let bounds=[0,1,0,1];for(let i=0;i<all.length;i++){if(i===0)bounds=[xs[i],xs[i],ys[i],ys[i]];else{bounds[0]=Math.min(bounds[0],xs[i]);bounds[1]=Math.max(bounds[1],xs[i]);bounds[2]=Math.min(bounds[2],ys[i]);bounds[3]=Math.max(bounds[3],ys[i]);}}bounds=[bounds[0]-.5,bounds[1]+.5,bounds[2]-.5,bounds[3]+.5];const a=setup(document.getElementById('coverage'),bounds);(s.coverage_map_cells||[]).forEach(p=>{a.ctx.fillStyle=p[2]>2?'#c197e3':p[2]===2?'#ffb648':'#69b8ff';const q=a.map(p[0],p[1]),size=Math.max(3,a.scale*.95);a.ctx.fillRect(q[0]-size/2,q[1]-size/2,size,size)});const b=setup(document.getElementById('difference'),bounds);lastTransform=b;if(r){r.map_cells.forEach(p=>{const v=Math.max(-1,Math.min(1,p[2]/D.native_settings.tolerance)),t=Math.abs(v),base=v>0?[255,100,90]:[77,163,255];b.ctx.fillStyle=`rgb(${base.map(k=>Math.round(224*(1-t)+k*t)).join(',')})`;const q=b.map(p[0],p[1]);const size=Math.max(4,b.scale*.95);b.ctx.fillRect(q[0]-size/2,q[1]-size/2,size,size)});document.getElementById('map-note').textContent=`${r.finding}. ${r.map_cells.length.toLocaleString()} map cells shown of ${r.statistics.cells.toLocaleString()} qualified cells. All cells are retained in CSV; map sampling does not affect statistics.`;}else{b.ctx.fillStyle='#8a97a6';b.ctx.fillText('No flight pair available',35,70);document.getElementById('map-note').textContent='At least two flight identities are needed for a comparison.';}}
    function change(){P.replaceChildren();D.states[+S.value].pairs.forEach(r=>P.add(new Option(`Flight ${r.a} / ${r.b} — ${r.statistics.cells} qualified cells`,`${r.a}-${r.b}`)));draw()}
    S.addEventListener('change',change);P.addEventListener('change',draw);window.addEventListener('resize',draw);document.querySelectorAll('[data-pair]').forEach(row=>row.addEventListener('click',()=>{S.value=row.dataset.state;change();P.value=row.dataset.pair;draw();document.getElementById('difference').scrollIntoView({block:'center',behavior:'smooth'})}));document.getElementById('difference').addEventListener('mousemove',e=>{if(!selected||!lastTransform)return;const rect=e.target.getBoundingClientRect(),x=(e.clientX-rect.left)*e.target.width/rect.width,y=(e.clientY-rect.top)*e.target.height/rect.height;let best=null,d=100;for(const p of selected.map_cells){const q=lastTransform.map(p[0],p[1]),v=(q[0]-x)**2+(q[1]-y)**2;if(v<d){d=v;best=p}}document.getElementById('hover').textContent=best?`E ${((best[0]+.5)*D.native_settings.cell).toFixed(3)}, N ${((best[1]+.5)*D.native_settings.cell).toFixed(3)}, dZ ${best[2].toFixed(4)} ${D.states[+S.value].units}`:'No displayed qualified cell at this position.'});change();
    </script></body></html>'''
    replacements={'CREATED':escape(result['created_utc']),'FLIGHTS':str(len(baseline['flights'])),
        'PAIRS':str(sum(p['supported'] for p in baseline['pairs'])),'COMPONENTS':str(len(baseline['connected_components'])),
        'COMMON':comparison,'SECTIONS':''.join(sections),'METHOD':escape(result['method']),'LIMITATIONS':findings,
        'TOL':number(result['native_settings']['tolerance']),'UNIT':escape(baseline['units']),
        'CELL':str(result['config']['cell_ft']),'MIN':str(result['config']['min_points']),
        'SCATTER':str(result['config']['max_scatter_ft']),'SLOPE':str(result['config']['max_slope']),'DATA':raw}
    for key,value in replacements.items():template=template.replace('__'+key+'__',value)
    (Path(folder)/'report.html').write_text(template,encoding='utf-8')
